div.style:
position: fixed; top: 0; left: 0; width: 100%; height: 100%; 
                    background: rgba(15, 23, 42, 0.65); backdrop-filter: blur(8px); 
                    -webkit-backdrop-filter: blur(8px);
                    z-index: 10001; display: flex; align-items: center; justify-content: center;
                    animation: ddcFadeIn 0.2s ease;

background: white; border-radius: 16px; padding: 40px 36px 32px 36px; 
                        text-align: center; box-shadow: 0 30px 80px rgba(0,0,0,0.5); 
                        max-width: 440px; width: 92%; animation: ddcSlideUp 0.35s cubic-bezier(0.16, 1, 0.3, 1);

width: 80px; height: 80px; background: #fef2f2; border-radius: 50%; 
                                margin: 5px auto; display: flex; align-items: center; justify-content: center;
                                border: 3px solid #fecaca;

button.style:
border-radius: 8px; padding: 10px 22px; font-size: 14px; font-weight: 500;
                                   border: 1px solid #d1d5db; color: #374151; background: white;
                                   transition: all 0.2s;

border-radius: 8px; padding: 10px 22px; font-size: 14px; font-weight: 500;
                                   background: #dc2626; color: white; border: none;
                                   box-shadow: 0 2px 8px rgba(220, 38, 38, 0.3);
                                   transition: all 0.2s;
